        changes = getChangesOnSelection(props, state.highlightedIndex, false)
      } else {
        const highlightedIndex = state.isOpen
          ? getHighlightedIndex(
              state.highlightedIndex,
              -1,
              props.items,
              props.isItemDisabled,
